/**************TEST CLASS DECLARATION*************/
public class APITest {}
/**************TEST SETUP BEGIN*************/
@BeforeClass
public static void setUpServer() throws Exception{
        // Find a free ephemeral port.
        int port;
        try (ServerSocket socket = new ServerSocket(0)) {
            port = socket.getLocalPort();
        }

        // ---- IotaConfig mock ------------------------------------------------
        IotaConfig config = mock(IotaConfig.class);
        when(config.getPort()).thenReturn(port);
        when(config.getApiHost()).thenReturn("127.0.0.1");
        when(config.getRemoteAuth()).thenReturn(null);
        when(config.getMaxBodyLength()).thenReturn(1_000_000);
        when(config.getMaxFindTransactions()).thenReturn(100);
        when(config.getMaxRequestsList()).thenReturn(1000);
        when(config.getMaxGetTrytes()).thenReturn(100);
        when(config.getRemoteLimitApi()).thenReturn(
                Collections.singletonList(RESTRICTED_CMD));
        when(config.getRemoteTrustedApiHosts()).thenReturn(Collections.emptyList());
        when(config.isTestnet()).thenReturn(false);
        when(config.getCoordinator()).thenReturn(Hash.NULL_HASH);
        when(config.getMaxDepth()).thenReturn(15);

        // ---- Service mocks --------------------------------------------------
        IXI ixi = mock(IXI.class);
        when(ixi.processCommand(anyString(), any())).thenReturn(null);

        TransactionRequester txRequester = mock(TransactionRequester.class);
        when(txRequester.getRequestedTransactions()).thenReturn(new Hash[0]);
        when(txRequester.numberOfTransactionsToRequest()).thenReturn(0);

        SpentAddressesService spentAddresses = mock(SpentAddressesService.class);
        when(spentAddresses.wasAddressSpentFrom(any())).thenReturn(false);

        Tangle tangle = mock(Tangle.class);
        when(tangle.getPersistanceSize()).thenReturn(0L);

        BundleValidator bundleValidator = mock(BundleValidator.class);

        // Snapshot mocks: index=0 for both, so isNodeSynchronized() returns false
        // (0 != 0 is false). Commands that require a synced node return ErrorResponse.
        Snapshot latestSnapshot = mock(Snapshot.class);
        when(latestSnapshot.getHash()).thenReturn(Hash.NULL_HASH);
        when(latestSnapshot.getIndex()).thenReturn(0);
        when(latestSnapshot.getInitialIndex()).thenReturn(0);
        when(latestSnapshot.getBalance(any())).thenReturn(null);

        Snapshot initialSnapshot = mock(Snapshot.class);
        when(initialSnapshot.getHash()).thenReturn(Hash.NULL_HASH);
        when(initialSnapshot.getIndex()).thenReturn(0);

        SnapshotProvider snapshotProvider = mock(SnapshotProvider.class);
        when(snapshotProvider.getLatestSnapshot()).thenReturn(latestSnapshot);
        when(snapshotProvider.getInitialSnapshot()).thenReturn(initialSnapshot);

        LedgerService ledgerService = mock(LedgerService.class);

        NeighborRouter neighborRouter = mock(NeighborRouter.class);
        when(neighborRouter.getNeighbors()).thenReturn(Collections.emptyList());
        when(neighborRouter.getConnectedNeighbors()).thenReturn(Collections.emptyMap());
        when(neighborRouter.addNeighbor(anyString()))
                .thenReturn(NeighborRouter.NeighborMutOp.OK);
        when(neighborRouter.removeNeighbor(anyString()))
                .thenReturn(NeighborRouter.NeighborMutOp.OK);

        TransactionProcessingPipeline txPipeline =
                mock(TransactionProcessingPipeline.class);
        when(txPipeline.getBroadcastStageQueue())
                .thenReturn(new LinkedBlockingQueue<>());

        TipSelector tipsSelector = mock(TipSelector.class);
        TipsViewModel tipsViewModel = new TipsViewModel();

        TransactionValidator txValidator = mock(TransactionValidator.class);

        MilestoneSolidifier milestoneSolidifier = mock(MilestoneSolidifier.class);
        when(milestoneSolidifier.getLatestMilestoneHash()).thenReturn(Hash.NULL_HASH);
        when(milestoneSolidifier.getLatestMilestoneIndex()).thenReturn(0);

        TransactionSolidifier txSolidifier = mock(TransactionSolidifier.class);

        // ---- Build and start server -----------------------------------------
        api = new API(config, ixi, txRequester, spentAddresses, tangle, bundleValidator,
                snapshotProvider, ledgerService, neighborRouter, tipsSelector,
                tipsViewModel, txValidator, milestoneSolidifier, txPipeline,
                txSolidifier);

        RestEasy restEasy = new RestEasy(config);
        api.init(restEasy);

        RestAssured.baseURI = "http://127.0.0.1";
        RestAssured.port = port;
    }
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
public void testAddNeighborsWithValidUriReturns200(){
        apiRequest()
                .body("{\"command\":\"addNeighbors\","
                        + "\"uris\":[\"tcp://192.168.1.1:15600\"]}")
        .when()
                .post("/")
        .then()
                .statusCode(200)
                .body("addedNeighbors", equalTo(1));
    }
/**************TEST METHOD END*************/
/**************TEST HELPER METHOD BEGIN*************/
private static RequestSpecification apiRequest(){
        return given()
                .header("X-IOTA-API-Version", "1")
                .contentType(ContentType.JSON);
    }
/**************TEST HELPER METHOD END*************/
/**************TEST TEARDOWN BEGIN*************/
@AfterClass
public static void tearDownServer(){
        if (api != null) {
            api.shutDown();
        }
    }
/**************TEST TEARDOWN END*************/


